 21	    public ReservationService(
 22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 23	        this.rooms = rooms;
 24	        this.store = store;
 25	        this.priceCalculator = priceCalculator;
 26	        this.emailSender = emailSender;
 27	    }
 28	
 29	    public synchronized Reservation create(NewReservation request) {
 30	        if (!request.checkOut().isAfter(request.checkIn())) {
 31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 32	        }
 33	        if (request.guests() < 1) {
 34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 35	        }
 36	
 37	        validateRatePlanRules(request);
 38	
 39	        Room room = rooms.find(request.roomNumber())
 40	                .orElseThrow(() -> new HotelException(
 41	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 42	        if (request.guests() > room.capacity()) {
 43	            throw new HotelException(
 44	                    ErrorCode.CAPACITY_EXCEEDED,
 45	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 46	        }
 47	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 48	            throw new HotelException(
 49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 50	        }
 51	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 52	        return store.add(request, price);
 53	    }
 54	
 55	    private void validateRatePlanRules(NewReservation request) {
 56	        switch (request.ratePlan()) {
 57	            case CORPORATE -> validateCorporate(request);
 58	            case WEEKEND_PACKAGE -> validateWeekendPackage(request);
 59	            case LONG_STAY -> validateLongStay(request);
 60	            default -> {}
 61	        }
 62	    }
 63	
 64	    private void validateCorporate(NewReservation request) {
 65	        String companyCode = request.companyCode();
 66	        if (companyCode == null || !isValidCorporateCode(companyCode)) {
 67	            throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid or missing company code for CORPORATE rate plan");
 68	        }
 69	    }
 70	
 71	    private boolean isValidCorporateCode(String code) {
 72	        return "TECNOSUL".equals(code) || "AGROVALE".equals(code) || "FARMAVIDA".equals(code);
 73	    }
 74	
 75	    private void validateWeekendPackage(NewReservation request) {
 76	        int nights = countNights(request.checkIn(), request.checkOut());
 77	        if (nights != 2) {
 78	            throw new HotelException(ErrorCode.INVALID_REQUEST, "WEEKEND_PACKAGE requires exactly 2 nights");
 79	        }
 80	        if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
 81	            throw new HotelException(ErrorCode.INVALID_REQUEST, "WEEKEND_PACKAGE check-in must be on Friday");
