103	    public Reservation find(long reservationId) {
104	        return store.find(reservationId)
105	                .orElseThrow(() -> new HotelException(
106	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
107	    }
108	
109	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
110	    public synchronized Reservation confirm(long reservationId) {
111	        Reservation reservation = find(reservationId);
112	        if (reservation.status() != ReservationStatus.PENDING) {
113	            throw notAllowed(reservation, "confirm");
114	        }
115	        reservation.confirmPayment();
116	        store.update(reservation);
117	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
118	        emailSender.send(
119	                reservation.guest().email(),
120	                "Reserva confirmada - " + HOTEL_NAME,
121	                confirmationEmailBody(reservation, receipt));
122	        return reservation;
123	    }
124	
125	    /**
126	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
127	     * reservation was never paid, so nothing comes back).
128	     */
129	    public synchronized Reservation cancel(long reservationId) {
130	        Reservation reservation = find(reservationId);
131	        if (reservation.status() != ReservationStatus.PENDING
132	                && reservation.status() != ReservationStatus.CONFIRMED) {
133	            throw notAllowed(reservation, "cancel");
134	        }
135	        BigDecimal refund = switch (reservation.ratePlan()) {
136	            case STANDARD -> reservation.amountPaid();
137	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
138	            case CORPORATE -> reservation.amountPaid();
139	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.50")));
140	            case LONG_STAY -> reservation.amountPaid();
141	        };
142	        reservation.cancel(refund);
143	        store.update(reservation);
144	        return reservation;
145	    }
146	
147	    public synchronized Reservation checkIn(long reservationId) {
148	        Reservation reservation = find(reservationId);
149	        if (reservation.status() != ReservationStatus.CONFIRMED) {
150	            throw notAllowed(reservation, "check in");
151	        }
152	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
153	        store.update(reservation);
154	        return reservation;
155	    }
156	
157	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
158	    public synchronized ReservationReceipt checkOut(long reservationId) {
159	        Reservation reservation = find(reservationId);
160	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
161	            throw notAllowed(reservation, "check out");
162	        }
163	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
164	        store.update(reservation);
165	        return new ReservationReceipt(reservation, roomOf(reservation));
166	    }
167	
168	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
169	    public ReservationReceipt receiptCopy(long reservationId) {
170	        Reservation reservation = find(reservationId);
171	        if (!reservation.isPaid()) {
172	            throw notAllowed(reservation, "issue a receipt for");
173	        }
174	        return new ReservationReceipt(reservation, roomOf(reservation));
175	    }
176	
177	    private Room roomOf(Reservation reservation) {
178	        return rooms.find(reservation.roomNumber()).orElseThrow();
179	    }
180	
181	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
182	        return "Olá, " + reservation.guest().name() + "!\n\n"
183	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
184	                + receipt.text() + "\n"
185	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
186	                + "Até breve!\n";
187	    }
188	
189	    private static HotelException notAllowed(Reservation reservation, String operation) {
190	        return new HotelException(
191	                ErrorCode.OPERATION_NOT_ALLOWED,
192	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
193	    }
194	}
