 20	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 21	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
 22	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
 23	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
 24	    static final BigDecimal WEEKEND_PACKAGE_STANDARD = new BigDecimal("520.00");
 25	    static final BigDecimal WEEKEND_PACKAGE_DELUXE = new BigDecimal("820.00");
 26	    static final BigDecimal WEEKEND_PACKAGE_SUITE = new BigDecimal("1200.00");
 27	
 28	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 29	        return switch (ratePlan) {
 30	            case STANDARD -> calculateStandard(room, checkIn, checkOut);
 31	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut);
 32	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 33	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 34	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 35	        };
 36	    }
 37	
 38	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut) {
 39	        int nights = 0;
 40	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 41	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 42	            subtotal = subtotal.add(nightPrice(room, night));
 43	            nights++;
 44	        }
 45	        return new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
 46	    }
 47	
 48	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut) {
 49	        int nights = 0;
 50	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 51	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 52	            subtotal = subtotal.add(nightPrice(room, night));
 53	            nights++;
 54	        }
 55	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 56	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 57	    }
 58	
 59	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 60	        int nights = 0;
 61	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 62	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 63	            subtotal = subtotal.add(nightPrice(room, night));
 64	            nights++;
 65	        }
 66	        BigDecimal discountRate = getCorporateDiscountRate(companyCode);
 67	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 68	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 69	    }
 70	
 71	    private BigDecimal getCorporateDiscountRate(String companyCode) {
 72	        if (companyCode == null) {
 73	            return BigDecimal.ZERO;
 74	        }
 75	        return switch (companyCode) {
 76	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
 77	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
 78	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA_DISCOUNT;
 79	            default -> BigDecimal.ZERO;
 80	        };
 81	    }
 82	
 83	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 84	        int nights = countNights(checkIn, checkOut);
 85	        BigDecimal packagePrice = switch (room.type()) {
 86	            case STANDARD -> WEEKEND_PACKAGE_STANDARD;
 87	            case DELUXE -> WEEKEND_PACKAGE_DELUXE;
 88	            case SUITE -> WEEKEND_PACKAGE_SUITE;
 89	        };
 90	        return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
 91	    }
 92	
 93	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
 94	        int nights = 0;
 95	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 96	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 97	            subtotal = subtotal.add(nightPrice(room, night));
 98	            nights++;
 99	        }
100	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
101	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
102	    }
103	
104	    BigDecimal nightPrice(Room room, LocalDate night) {
105	        BigDecimal nightlyRate = room.nightlyRate();
106	        if (isHighSeason(night)) {
107	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
108	        }
109	        return cents(nightlyRate);
110	    }
111	
112	    private static int countNights(LocalDate checkIn, LocalDate checkOut) {
113	        int nights = 0;
114	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
115	            nights++;
116	        }
117	        return nights;
118	    }
119	
120	    /** High season: from December 15 to the end of February, and the whole of July. */
121	    static boolean isHighSeason(LocalDate date) {
122	        Month month = date.getMonth();
123	        return month == Month.JANUARY
124	                || month == Month.FEBRUARY
125	                || month == Month.JULY
126	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
127	    }
128	
129	    static BigDecimal cents(BigDecimal value) {
130	        return value.setScale(2, RoundingMode.HALF_EVEN);
131	    }
132	}

